package com.safepath.backend.safety.safetyguardianstore;
import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component;
@Component @ConditionalOnProperty(name="safepath.safety-guardian-store.sync.enabled",havingValue="true") public class SafetyGuardianStoreSyncScheduler {private final SafetyGuardianStoreSyncService service;private final int max;public SafetyGuardianStoreSyncScheduler(SafetyGuardianStoreSyncService service,@Value("${safepath.safety-guardian-store.sync.max-pages:0}")int max){this.service=service;this.max=max;}@Scheduled(initialDelayString="${safepath.safety-guardian-store.sync.initial-delay-ms:0}",fixedDelayString="${safepath.safety-guardian-store.sync.interval-ms:7776000000}")public void sync(){service.syncAll(max);}}
